// Code node "Build find request". Reads the webhook body and builds one looot job run.
// Body: {"first_name": "Ada", "last_name": "Lovelace", "domain": "example.com"}
// Also accepts "name" (full name) and "website" or "url" for the domain.
const MAX_COST_PER_CALL = 0.05; // USD cap for this lookup across every provider tried
const MAX_ATTEMPTS = 3;          // providers to try before giving up

const body = $input.first().json.body ?? $input.first().json;
const clean = (v) => (typeof v === "string" ? v.trim() : "");
let first = clean(body.first_name ?? body.firstName);
let last = clean(body.last_name ?? body.lastName);
const full = clean(body.name ?? body.full_name);
if (!first && full) {
  const parts = full.split(/\s+/);
  first = parts[0];
  last = last || parts.slice(1).join(" ");
}
let domain = clean(body.domain ?? body.website ?? body.url).toLowerCase();
domain = domain.replace(/^[a-z]+:\/\//, "").replace(/^www\./, "").split(/[/?#]/)[0];

if (!first || !last || !domain.includes(".") || /[\s@]/.test(domain)) {
  return [{ json: { next: "respond", response: { ok: false, error: "Send first_name, last_name and domain (or name and website).", cost_usd: 0 } } }];
}

const input = { first_name: first, last_name: last, domain };
const key = ["n8n-email-find", domain, first, last].join(":").toLowerCase().replace(/[^a-z0-9:._-]/g, "-").slice(0, 180);
return [{
  json: {
    next: "find",
    lead: input,
    request: {
      endpointId: "job:people.email.find",
      input,
      idempotencyKey: key,
      fallback: { enabled: true, maxAttempts: MAX_ATTEMPTS, maxCostUsd: MAX_COST_PER_CALL },
    },
  },
}];

// Code node "Build verify request". Reads the find run; if it found an address, builds the
// verification run, otherwise answers right away (a miss or a failed call costs $0).
const MAX_COST_PER_CALL = 0.05;
const MAX_ATTEMPTS = 3;

const run = $input.first().json;
const lead = $("Build find request").first().json.lead;
const cost = typeof run.actualCost === "number" ? run.actualCost : 0;

function findEmail(r) {
  const re = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
  const norm = r.normalized && r.normalized.fields && r.normalized.fields.email;
  if (typeof norm === "string" && re.test(norm)) return norm.match(re)[0];
  const m = JSON.stringify(r.result ?? "").match(re);
  return m ? m[0] : null;
}

if (!run.status) {
  const err = run.error || {};
  return [{ json: { next: "respond", response: { ok: false, lead, error: `${err.code || "error"}: ${err.message || "looot refused the call"}`, top_up_url: run.topUpUrl || null, cost_usd: 0 } } }];
}
if (run.status !== "completed") {
  const terminal = ["failed", "blocked", "stopped"].includes(run.status);
  return [{ json: { next: "respond", response: { ok: terminal ? false : true, lead, email: null, status: run.status, run_id: run.runId, note: terminal ? (run.error && run.error.message) || run.status : "Still running. GET https://api.looot.ai/v1/runs/" + run.runId + " later; it is free to read.", cost_usd: cost } } }];
}
const email = findEmail(run);
if (!email) {
  return [{ json: { next: "respond", response: { ok: true, lead, email: null, note: "No provider found an address.", served_by: run.route && run.route.servedBy || null, cost_usd: cost } } }];
}
return [{
  json: {
    next: "verify",
    lead,
    email,
    find_cost: cost,
    find_served_by: (run.route && run.route.servedBy) || null,
    request: {
      endpointId: "job:people.email.verify",
      input: { email },
      idempotencyKey: ("n8n-email-verify:" + email).toLowerCase().slice(0, 180),
      fallback: { enabled: true, maxAttempts: MAX_ATTEMPTS, maxCostUsd: MAX_COST_PER_CALL },
    },
  },
}];

// Code node "Shape answer". Combines the found email with its verification status.
const run = $input.first().json;
const prev = $("Build verify request").first().json;
const WORDS = {
  valid: "valid", deliverable: "valid", ok: "valid", safe: "valid", verified: "valid",
  invalid: "invalid", undeliverable: "invalid", bounce: "invalid",
  catchall: "catch_all", catch_all: "catch_all", accept_all: "catch_all", acceptall: "catch_all",
  risky: "risky", unknown: "unknown",
};
function status(r) {
  const f = (r.normalized && r.normalized.fields) || {};
  const res = r.result && typeof r.result === "object" ? r.result : {};
  const data = res.data && typeof res.data === "object" ? res.data : {};
  for (const v of [f.status, f.email_status, res.email_status, res.verdict, res.result, res.status, data.status, data.result]) {
    if (typeof v === "string" && v.trim()) return WORDS[v.trim().toLowerCase()] || "unknown";
  }
  return "unknown";
}
const verifyCost = typeof run.actualCost === "number" ? run.actualCost : 0;
return [{
  json: {
    response: {
      ok: true,
      lead: prev.lead,
      email: prev.email,
      email_status: run.status === "completed" ? status(run) : "unknown",
      verify_run_status: run.status || (run.error && run.error.code) || "error",
      served_by: prev.find_served_by,
      cost_usd: Number((prev.find_cost + verifyCost).toFixed(6)),
    },
  },
}];
